function mir(c,sx,sz){return c.map(p=>[sx>0?p[0]:-1-p[0], sz>0?p[1]:-1-p[1]]);}
// tile a straight colinear run with 1x4/1x3/1x2/1x1
function layLine(cells,color,phase){
  const P={1:'3005',2:'3004',3:'3622',4:'3010'};
  const horiz = cells.length<2 || cells[1][0]!==cells[0][0];
  let i=0; const segs=[];
  if(phase && cells.length>=3){segs.push(2); i=2;}
  while(i<cells.length){const rem=cells.length-i; const s=rem>=4?4:rem; segs.push(s); i+=s;}
  let pos=0;
  for(const s of segs){const c=cells[pos]; put(P[s],color,c[0],c[1],horiz?0:90); pos+=s;}
}
// tile a staircase chain with 1x2 pairs
function layChain(cells,color,phase){
  let i=0;
  if(phase){put('3005',color,cells[0][0],cells[0][1],0); i=1;}
  while(i<cells.length){
    if(i+1<cells.length){const a=cells[i],b=cells[i+1];
